changeSet.sql:
CREATE TABLE profiles ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, username CITEXT NOT NULL UNIQUE, full_name VARCHAR(64), profile_image_url TEXT, bio VARCHAR(150), website_url TEXT, gender TEXT CHECK (gender IS NULL OR gender IN ('male','female','prefer_not_to_say','custom')), custom_gender TEXT, is_private BOOLEAN NOT NULL DEFAULT FALSE, is_verified BOOLEAN NOT NULL DEFAULT FALSE, followers_count INTEGER NOT NULL DEFAULT 0, following_count INTEGER NOT NULL DEFAULT 0, posts_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), deleted_at TIMESTAMPTZ,
CONSTRAINT PROFILES_GENDER_CHK CHECK ( (gender = 'custom' AND custom_gender IS NOT NULL) OR (gender IS DISTINCT FROM 'custom' AND custom_gender IS NULL) ), CONSTRAINT PROFILES_USER_FK FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE );
CREATE INDEX idx_profiles_username ON profiles(username) WHERE deleted_at IS NULL; CREATE INDEX idx_profiles_user_id ON profiles(user_id) WHERE deleted_at IS NULL;

ALTER TABLE profiles DROP CONSTRAINT IF EXISTS profiles_user_fk;
DROP INDEX IF EXISTS idx_profiles_user_id;
ALTER TABLE profiles DROP CONSTRAINT IF EXISTS profiles_user_id_key;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_name = 'profiles' AND column_name = 'user_id_uuid'
    ) THEN
        ALTER TABLE profiles ADD COLUMN user_id_uuid UUID;
    END IF;
END $$;

UPDATE profiles p
SET user_id_uuid = u.id_uuid
FROM users u
WHERE p.user_id = u.id;

ALTER TABLE profiles ALTER COLUMN user_id_uuid SET NOT NULL;
ALTER TABLE profiles DROP COLUMN user_id;
ALTER TABLE profiles RENAME COLUMN user_id_uuid TO user_id;
ALTER TABLE profiles ADD CONSTRAINT profiles_user_id_key UNIQUE (user_id);

ALTER TABLE users DROP CONSTRAINT IF EXISTS users_pkey;
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_id_uuid_key;
ALTER TABLE users RENAME COLUMN id TO id_legacy_tmp;
ALTER TABLE users RENAME COLUMN id_uuid TO id;
ALTER TABLE users ADD CONSTRAINT users_pkey PRIMARY KEY (id);
ALTER TABLE users ALTER COLUMN id SET DEFAULT uuid_generate_v7();
ALTER TABLE users DROP COLUMN id_legacy_tmp;

ALTER TABLE profiles
    ADD CONSTRAINT profiles_user_fk
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;

CREATE INDEX idx_profiles_user_id ON profiles(user_id) WHERE deleted_at IS NULL;

